// TestClient provides a testsuite-compatible Client
type TestSecretsClient struct {
	env       *testsuite.TestWorkflowEnvironment
	workflows SecretsWorkflows
}

var _ SecretsClient = &TestSecretsClient{}

// NewTestSecretsClient initializes a new TestSecretsClient value
func NewTestSecretsClient(env *testsuite.TestWorkflowEnvironment, workflows SecretsWorkflows, activities SecretsActivities) *TestSecretsClient {
	if workflows != nil {
		RegisterSecretsWorkflows(env, workflows)
	}
	if activities != nil {
		RegisterSecretsActivities(env, activities)
	}
	return &TestSecretsClient{env, workflows}
}

// CreateAccess executes a(n) secrets.v1.CreateAccess workflow in the test environment
func (c *TestSecretsClient) CreateAccess(ctx context.Context, req *CreateAccessInput, opts ...*CreateAccessOptions) (*CreateAccessOutput, error) {
	run, err := c.CreateAccessAsync(ctx, req, opts...)
	if err != nil {
		return nil, err
	}
	return run.Get(ctx)
}

// CreateAccessAsync executes a(n) secrets.v1.CreateAccess workflow in the test environment
func (c *TestSecretsClient) CreateAccessAsync(ctx context.Context, req *CreateAccessInput, options ...*CreateAccessOptions) (CreateAccessRun, error) {
	var o *CreateAccessOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewCreateAccessOptions()
	}
	opts, err := o.Build(req.ProtoReflect())
	if err != nil {
		return nil, fmt.Errorf("error initializing client.StartWorkflowOptions: %w", err)
	}
	return &testCreateAccessRun{client: c, env: c.env, opts: &opts, req: req, workflows: c.workflows}, nil
}

// GetCreateAccess is a noop
func (c *TestSecretsClient) GetCreateAccess(ctx context.Context, workflowID string, runID string) CreateAccessRun {
	return &testCreateAccessRun{env: c.env, workflows: c.workflows}
}

// CancelWorkflow requests cancellation of an existing workflow execution
func (c *TestSecretsClient) CancelWorkflow(ctx context.Context, workflowID string, runID string) error {
	c.env.CancelWorkflow()
	return nil
}

// TerminateWorkflow terminates an existing workflow execution
func (c *TestSecretsClient) TerminateWorkflow(ctx context.Context, workflowID string, runID string, reason string, details ...interface{}) error {
	return c.CancelWorkflow(ctx, workflowID, runID)
}

var _ CreateAccessRun = &testCreateAccessRun{}

// testCreateAccessRun provides convenience methods for interacting with a(n) secrets.v1.CreateAccess workflow in the test environment
type testCreateAccessRun struct {
	client    *TestSecretsClient
	env       *testsuite.TestWorkflowEnvironment
	isStarted atomic.Bool
	opts      *client.StartWorkflowOptions
	req       *CreateAccessInput
	workflows SecretsWorkflows
}

// Cancel requests cancellation of a workflow in execution, returning an error if applicable
func (r *testCreateAccessRun) Cancel(ctx context.Context) error {
	return r.client.CancelWorkflow(ctx, r.ID(), r.RunID())
}

// Get retrieves a test secrets.v1.CreateAccess workflow result
func (r *testCreateAccessRun) Get(context.Context) (*CreateAccessOutput, error) {
	if r.isStarted.CompareAndSwap(false, true) {
		r.env.ExecuteWorkflow(CreateAccessWorkflowName, r.req)
	}
	if !r.env.IsWorkflowCompleted() {
		return nil, errors.New("workflow in progress")
	}
	if err := r.env.GetWorkflowError(); err != nil {
		return nil, err
	}
	var result CreateAccessOutput
	if err := r.env.GetWorkflowResult(&result); err != nil {
		return nil, err
	}
	return &result, nil
}

// ID returns a test secrets.v1.CreateAccess workflow run's workflow ID
func (r *testCreateAccessRun) ID() string {
	if r.opts != nil {
		return r.opts.ID
	}
	return ""
}

// Run noop implementation
func (r *testCreateAccessRun) Run() client.WorkflowRun {
	return nil
}

// RunID noop implementation
func (r *testCreateAccessRun) RunID() string {
	return ""
}

// Terminate terminates a workflow in execution, returning an error if applicable
func (r *testCreateAccessRun) Terminate(ctx context.Context, reason string, details ...interface{}) error {
	return r.client.TerminateWorkflow(ctx, r.ID(), r.RunID(), reason, details...)
}
